from rdkit import Chem
mol = Chem.MolFromSmiles('N#CC1CCc2[nH]c3ccccc3c2C1')
if mol:
    print('Valid SMILES')
    print(f'Num atoms: {mol.GetNumAtoms()}')
    for atom in mol.GetAtoms():
        print(f'Atom {atom.GetIdx()}: {atom.GetSymbol()}, hybridization={atom.GetHybridization()}, degree={atom.GetDegree()}')
